import networkx as nx

edges = [(0, 12), (0, 13), (0, 14), (1, 10), (1, 13), (2, 10), (3, 10), (3, 14), (4, 9), (4, 10), (4, 12), (5, 14), (5, 11), (5, 7), (5, 9), (6, 7)]

G = nx.Graph()
G.add_nodes_from(range(15))
G.add_edges_from(edges)

print("Is bipartite:", nx.is_bipartite(G))
try:
    cycles = nx.cycle_basis(G)
    if cycles:
        girth = min(len(c) for c in cycles)
        # Note: cycle_basis doesn't always give the shortest cycle, but for small graphs it's usually fine.
        # Let's use a better way to find girth
        def get_girth(G):
            girth = float('inf')
            for n in G.nodes():
                # BFS
                dist = {n: 0}
                queue = [n]
                parent = {n: None}
                while queue:
                    curr = queue.pop(0)
                    for neighbor in G.neighbors(curr):
                        if neighbor not in dist:
                            dist[neighbor] = dist[curr] + 1
                            parent[neighbor] = curr
                            queue.append(neighbor)
                        elif parent[curr] != neighbor:
                            girth = min(girth, dist[curr] + dist[neighbor] + 1)
            return girth
        print("Girth:", get_girth(G))
    else:
        print("Girth: infinity")
except Exception as e:
    print(e)
print("Edges:", G.number_of_edges())

import networkx as nx
from itertools import combinations
import random

def find_graph():
    for _ in range(10000):
        G = nx.Graph()
        G.add_nodes_from(range(15))

        A = list(range(7))
        B = list(range(7, 15))

        edges = []
        for i in A:
            for j in B:
                edges.append((i, j))

        random.shuffle(edges)

        for e in edges:
            G.add_edge(*e)

            valid = True
            for u1, u2 in combinations(A, 2):
                shared = sum(1 for b in B if G.has_edge(u1, b) and G.has_edge(u2, b))
                if shared > 1:
                    valid = False
                    break

            if not valid:
                G.remove_edge(*e)

            if G.number_of_edges() >= 16:
                # check if any isolated
                if all(d > 0 for n, d in G.degree()):
                    return list(G.edges())

    return None

edges = find_graph()
if edges:
    flat = []
    for u, v in edges:
        if u > v: u, v = v, u
        flat.extend([u, v])
    print(flat)
else:
    print("Not found")

